1975: // A deterministic, bounded M1 front-end model.  The caller owns dynamic
1976: // instruction completion; this class only owns admission and Tag scheduling.
1977: class paper_frontend {
1978:  public:
1979:   explicit paper_frontend(config cfg) : m_cfg(cfg) {
1980:     check_tag_hash_bankrow(cfg.tag_hash_bankrow, false, cfg.finite_service,
1981:                            cfg.logical_sets, cfg.tag_banks);
1982:     check_progressive_wakeup_mode(cfg.progressive_wakeup,
1983:         static_cast<unsigned>(mode::PAPER_BASE), cfg.finite_service);
1984:     assert(m_cfg.pib_entries > 0);
1985:     assert(m_cfg.tag_banks > 0);
1986:     assert(m_cfg.tag_requests_per_bank_per_cycle > 0);
1987:     assert(m_cfg.tag_requests_per_cycle > 0);
1988:   }
1989: 
1990:   bool enabled() const { return m_cfg.selected_mode != mode::LEGACY; }
1991: 
1992:   bool try_admit(uint64_t dynamic_instruction_id) {
1993:     if (!enabled()) return true;
1994:     if (m_live_instructions.count(dynamic_instruction_id)) return true;
1995:     if (m_live_instructions.size() >= m_cfg.pib_entries) {
1996:       ++m_pib_full_events;
1997:       ++m_pib_full_stall_cycles;
1998:       ++m_nonexclusive_pib_full_cycles;
1999:       ++m_frontend_stall_cycles;
2000:       return false;
2001:     }
2002:     m_live_instructions.insert(dynamic_instruction_id);
2003:     ++m_admits;
2004:     m_pib_peak = std::max(m_pib_peak, m_live_instructions.size());
2005:     return true;
2006:   }
2007: 
2008:   void retire(uint64_t dynamic_instruction_id) {
2009:     if (!enabled()) return;
2010:     const size_t erased = m_live_instructions.erase(dynamic_instruction_id);
2011:     assert(erased == 1 && "DTC PIB release requires one admitted instruction");
2012:     ++m_retires;
2013:   }
2014: 
2015:   void begin_cycle(uint64_t cycle) {
2016:     if (cycle == m_cycle) return;
2017:     m_cycle = cycle;
2018:     m_total_served_this_cycle = 0;
2019:     std::fill(m_served_per_bank.begin(), m_served_per_bank.end(), 0);
2020:   }
2021: 
2022:   // Must be called once per modeled LD/ST cycle so occupancy does not depend
2023:   // on whether that cycle happens to contain Tag work.
2024:   void sample_cycle(uint64_t cycle) {
2025:     if (!enabled() || cycle == m_last_occupancy_sample_cycle) return;
2026:     m_last_occupancy_sample_cycle = cycle;
2027:     m_pib_occupancy_cycle_sum += m_live_instructions.size();
2028:     ++m_pib_occupancy_sample_cycles;
2029:   }
2030: 
2031:   unsigned tag_bank(uint64_t line_address, unsigned logical_set_count) const {
2032:     assert(logical_set_count > 0);
2033:     const unsigned logical_set =
2034:         static_cast<unsigned>((line_address / kLogicalLineBytes) % logical_set_count);
2035:     return logical_set % m_cfg.tag_banks;
2036:   }
2037: 
2038:   bool try_serve_tag(uint64_t cycle, uint64_t line_address,
2039:                      unsigned logical_set_count) {
2040:     if (!enabled()) return true;
2041:     begin_cycle(cycle);
2042:     const unsigned bank = tag_bank(line_address, logical_set_count);
2043:     if (m_total_served_this_cycle >= m_cfg.tag_requests_per_cycle ||
2044:         m_served_per_bank[bank] >= m_cfg.tag_requests_per_bank_per_cycle) {
2045:       ++m_tag_conflicts;
2046:       ++m_tag_conflict_stall_cycles;
2047:       ++m_nonexclusive_tag_conflict_cycles;
2048:       ++m_frontend_stall_cycles;
2049:       return false;
2050:     }
2051:     ++m_served_per_bank[bank];
2052:     ++m_requests_per_bank[bank];
2053:     ++m_total_served_this_cycle;
2054:     ++m_tag_requests;
2055:     return true;

