709:   void complete(physical_identity identity) {
710:     assert(fill_identity_matches(identity) &&
711:            "OO fill must match the original physical generation");
712:     physical_line &physical = m_phys[identity.id];
713:     assert(!physical.ready && "OO fill must wake each waiter exactly once");
714:     if (m_cfg.finite_service) {
715:       assert(m_service_cycle != UINT64_MAX);
716:       for (const auto &pending : m_service_returns)
717:         assert(pending.physical.id != identity.id ||
718:                pending.physical.generation != identity.generation);
719:       if (m_cfg.progressive_wakeup) physical.return_cycle = m_service_cycle;
720:       m_service_returns.push_back({identity, m_service_cycle + 1, 0});
721:       return;
722:     }
723:     physical.ready = true;
724:     for (const waiter &waiting : physical.waiters) {
725:       entry *owner = find_entry_by_slot(waiting.slot, waiting.slot_generation);
726:       assert(owner && has_reference(*owner, identity) &&
727:              "stale fill cannot wake a reused OO PIB slot");
728:       assert(owner->pending_dependencies);
729:       --owner->pending_dependencies;
730:       ++m_wakeups;
731:     }
732:     physical.waiters.clear();
733:     assert_shadow_refs();
734:   }
735: 
736:   // ready retains its X2 meaning: broadcast finished. AD's data_ready is
737:   // exposed only at this unchanged +1 metadata edge. Unnotified consumers
738:   // still own a pending dependency even when the data itself is available.
739:   void advance_service(uint64_t cycle) {
740:     if (!m_cfg.finite_service || cycle == m_service_cycle) return;
741:     m_service_cycle = cycle;
742:     unsigned budget = 4;
743:     while (!m_service_returns.empty() &&
744:            m_service_returns.front().ready_cycle <= cycle) {
745:       auto &pending = m_service_returns.front();
746:       assert(fill_identity_matches(pending.physical));
747:       auto &physical = m_phys[pending.physical.id];
748:       if (m_cfg.progressive_wakeup) physical.data_ready = true;
749:       while (budget && pending.next_waiter < physical.waiters.size()) {
750:         const auto &waiting = physical.waiters[pending.next_waiter++];
751:         entry *owner = find_entry_by_slot(waiting.slot, waiting.slot_generation);
752:         assert(owner && has_reference(*owner, pending.physical));
753:         assert(owner->pending_dependencies);
754:         --owner->pending_dependencies;
755:         if (m_cfg.progressive_wakeup) {
756:           if (!physical.notified) physical.first_notify_cycle = cycle;
757:           physical.last_notify_cycle = cycle;
758:           ++physical.notified;
759:         }
760:         ++m_wakeups;
761:         --budget;
762:       }
763:       if (pending.next_waiter != physical.waiters.size()) {
764:         if (m_cfg.progressive_wakeup && pending.next_waiter) {
765:           // Early retirement allows slot reuse and arbitrarily long merge
766:           // streams. Discard only the consumed prefix; the live cursor still
767:           // names the same physical generation and unnotified slot suffix.
768:           physical.waiters.erase(physical.waiters.begin(),
769:                                 physical.waiters.begin() + pending.next_waiter);
770:           pending.next_waiter = 0;
771:         }
772:         break;
773:       }
774:       if (m_cfg.progressive_wakeup) {
775:         ++m_broadcasts_finished;
776:         ++m_fanout_hist[std::min<uint64_t>(32, physical.notified)];
777:         m_first_notify_sum += physical.first_notify_cycle;
778:         m_last_notify_sum += physical.last_notify_cycle;
779:         m_broadcast_span_sum += physical.last_notify_cycle - physical.first_notify_cycle;
780:       }
781:       physical.ready = true;
782:       physical.waiters.clear();
783:       m_service_returns.pop_front();
784:     }

