59: // Absolute core-cycle quota; checking availability never consumes a grant.
60: // Commit only after the owning operation actually succeeds.
61: class service_quota {
62:  public:
63:   explicit service_quota(unsigned width = 1) : m_width(width) { assert(width); }
64:   bool available(uint64_t cycle) const {
65:     return cycle != m_cycle || m_used < m_width;
66:   }
67:   void commit(uint64_t cycle) {
68:     assert(available(cycle));
69:     if (cycle != m_cycle) { m_cycle = cycle; m_used = 0; }
70:     ++m_used;
71:   }
72:  private:
73:   unsigned m_width;
74:   unsigned m_used = 0;
75:   uint64_t m_cycle = UINT64_MAX;
76: };
